$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-publish-'.bin2hex(random_bytes(5));function kalite_filo_admin_config():array{global $root;return['data_root'=>$root];}function kalite_filo_admin_ensure_private_directory(string $path):void{if(!is_dir($path)&&!mkdir($path,0700,true)&&!is_dir($path))throw new RuntimeException('directory');}function kalite_filo_admin_vehicle_store_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'drafts'.DIRECTORY_SEPARATOR.'vehicles.json';}function kalite_filo_admin_article_store_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'drafts'.DIRECTORY_SEPARATOR.'articles.json';}function kalite_filo_admin_media_catalog_path():string{global $root;return $root.DIRECTORY_SEPARATOR.'media'.DIRECTORY_SEPARATOR.'library'.DIRECTORY_SEPARATOR.'library.json';}function kalite_filo_admin_assert_vehicle_uniqueness(array $records):void{$seen=[];foreach($records as $record){$key=($record['id']??'').'|'.($record['sourceId']??'').'|'.($record['slug']??'');if(isset($seen[$key]))throw new InvalidArgumentException();$seen[$key]=true;}}function kalite_filo_admin_vehicle_records():array{$records=[];foreach(range(1,4)as$i)$records[]=['id'=>'vehicle-'.$i,'sourceId'=>'SOURCE-'.$i,'slug'=>'vehicle-'.$i,'featured'=>true,'publicationStatus'=>'published','priceAmountMinor'=>10000,'coverImage'=>['src'=>'/vehicle.jpg']];return$records;}function kalite_filo_admin_article_drafts():array{return[['id'=>'article-one','coverMediaId'=>null,'locales'=>['tr'=>['status'=>'ready']]]];}function kalite_filo_admin_media_records():array{return[['id'=>str_repeat('a',32),'checksum'=>str_repeat('b',64)]];}function kalite_filo_admin_taxonomy():array{return['make'=>[['value'=>'Renault']]];}function publish_assert(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);}function publish_remove(string $path):void{if(!is_dir($path))return;foreach(scandir($path)?:[]as$entry){if($entry==='.'||$entry==='..')continue;$item=$path.DIRECTORY_SEPARATOR.$entry;is_dir($item)?publish_remove($item):@unlink($item);}@rmdir($path);}require_once dirname(__DIR__).'/publishing-store.php';
try{mkdir(dirname(kalite_filo_admin_vehicle_store_path()),0700,true);file_put_contents(kalite_filo_admin_vehicle_store_path(),'{}');file_put_contents(kalite_filo_admin_article_store_path(),'{}');$_SESSION['identity']=['id'=>'owner'];$changes=kalite_filo_admin_unpublished_changes();publish_assert(count($changes)===2&&strlen($changes[0]['fingerprint'])===64,'Changes must use content fingerprints.');$request=kalite_filo_admin_create_staging_publish_request();publish_assert($request['status']==='awaiting_runner'&&$request['target']==='staging'&&strlen($request['snapshotHash'])===64,'Staging request must freeze a runner-pending snapshot.');$duplicate=kalite_filo_admin_create_staging_publish_request();publish_assert($duplicate['id']===$request['id'],'The same pending snapshot must be idempotent.');$loaded=kalite_filo_admin_publish_request($request['id']);publish_assert(is_array($loaded)&&($loaded['snapshotHash']??null)===$request['snapshotHash'],'A valid request must be available to the trusted runner handoff.');publish_assert(kalite_filo_admin_publish_request('../'.$request['id'])===null&&kalite_filo_admin_publish_request('publish-invalid')===null,'Runner handoff lookup must reject traversal and malformed IDs.');$safe=kalite_filo_admin_safe_publish_request($request);publish_assert(!array_key_exists('snapshot',$safe)&&!array_key_exists('fingerprint',$safe['changes'][0])&&$safe['changeCount']===2,'Browser history must not expose private snapshot fingerprints.');publish_assert(count(kalite_filo_admin_publish_requests())===1,'Private request history must round-trip.');$invalid=kalite_filo_admin_staging_publish_payload();$invalid['featuredVehicleIds']=['vehicle-1'];publish_assert(kalite_filo_admin_validate_staging_publish_payload($invalid)['valid']===false,'Featured invariant must block publish.');}finally{publish_remove($root);}fwrite(STDOUT,"Admin publishing store tests passed.\n");

$root=sys_get_temp_dir().DIRECTORY_SEPARATOR.'kalite-filo-publish-result-'.bin2hex(random_bytes(5));
try{mkdir(dirname(kalite_filo_admin_vehicle_store_path()),0700,true);file_put_contents(kalite_filo_admin_vehicle_store_path(),'{}');file_put_contents(kalite_filo_admin_article_store_path(),'{}');$_SESSION['identity']=['id'=>'owner'];$request=kalite_filo_admin_create_staging_publish_request();$hash=$request['snapshotHash'];try{kalite_filo_admin_transition_publish_request($request['id'],$hash,'complete',[]);throw new RuntimeException('Completion before start must fail.');}catch(DomainException){}try{kalite_filo_admin_transition_publish_request($request['id'],str_repeat('0',64),'start');throw new RuntimeException('Wrong snapshot hash must fail.');}catch(InvalidArgumentException){}$running=kalite_filo_admin_transition_publish_request($request['id'],$hash,'start');publish_assert($running['status']==='running'&&is_string($running['startedAt']),'Start must enter running state.');publish_assert(kalite_filo_admin_transition_publish_request($request['id'],$hash,'start')['startedAt']===$running['startedAt'],'Repeated start must be idempotent.');$stages=array_fill_keys(['materialization','validation','build','release','deployment','smoke'],'passed');$result=['outcome'=>'succeeded','manifestHash'=>str_repeat('a',64),'artifactHash'=>str_repeat('b',64),'stages'=>$stages,'summary'=>'Staging checks passed.'];$complete=kalite_filo_admin_transition_publish_request($request['id'],$hash,'complete',$result);publish_assert($complete['status']==='staging_succeeded'&&($complete['result']['reportedBy']??null)==='owner','Successful completion must become terminal and retain reporter identity.');publish_assert(kalite_filo_admin_transition_publish_request($request['id'],$hash,'complete',$result)['completedAt']===$complete['completedAt'],'Repeated identical completion must be idempotent.');publish_assert(kalite_filo_admin_unpublished_changes()===[],'A successful staging result must become the unpublished-change baseline.');$invalidStages=$stages;$invalidStages['smoke']='skipped';try{kalite_filo_admin_normalize_runner_result(['outcome'=>'succeeded','manifestHash'=>str_repeat('a',64),'artifactHash'=>str_repeat('b',64),'stages'=>$invalidStages]);throw new RuntimeException('Successful result with skipped stage must fail.');}catch(InvalidArgumentException){}try{kalite_filo_admin_normalize_runner_result(['outcome'=>'failed','manifestHash'=>str_repeat('a',64),'artifactHash'=>'','stages'=>$stages]);throw new RuntimeException('Failed result without failed stage must fail.');}catch(InvalidArgumentException){}$failedStages=$stages;$failedStages['materialization']='failed';foreach(['validation','build','release','deployment','smoke']as$stage)$failedStages[$stage]='skipped';$earlyFailure=kalite_filo_admin_normalize_runner_result(['outcome'=>'failed','manifestHash'=>'','artifactHash'=>'','stages'=>$failedStages]);publish_assert($earlyFailure['manifestHash']===null,'A pre-materialization failure may omit unavailable hashes.');$cleared=kalite_filo_admin_clear_publish_history();publish_assert($cleared['deleted']===1&&kalite_filo_admin_publish_requests()===[],'Terminal history must be clearable.');publish_assert(kalite_filo_admin_unpublished_changes()===[],'Clearing history must preserve the successful baseline.');}finally{publish_remove($root);}fwrite(STDOUT,"Admin publishing result transition tests passed.\n");
